const btn = document.querySelector('.ai4a11y-plain-btn');
if (!btn) return true; // before enable
const rect = btn.getBoundingClientRect();
if (rect.width < 24 || rect.height < 24) return false;
// Verify button fits within viewport
if (rect.right > 320) return false;
// Verify document does not have horizontal overflow
return document.documentElement.scrollWidth <= 320;

